[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false);$ErrorActionPreference="Stop";$records=ConvertFrom-Json $env:V5_RECORDS; $filter=($records|ForEach-Object {"ProcessId="+$_.pid}) -join " OR ";$found=@(Get-CimInstance Win32_Process -Filter $filter);$ports=@($records|ForEach-Object {[int]$_.port}|Select-Object -Unique);$listeners=@(Get-NetTCPConnection -LocalPort $ports -State Listen -ErrorAction SilentlyContinue);$result=@($records|ForEach-Object {$r=$_;$p=@($found|Where-Object {$_.ProcessId -eq $r.pid});[pscustomobject]@{recordedPid=$r.pid;port=$r.port;recordedCreation=$r.created;recordedJar=$r.jar;present=($p.Count -gt 0);observed=@($p|ForEach-Object {[pscustomobject]@{pid=$_.ProcessId;created=$_.CreationDate.ToUniversalTime().ToString("o");commandLine=$_.CommandLine}});listenerPids=@($listeners|Where-Object {$_.LocalPort -eq $r.port}|ForEach-Object {$_.OwningProcess})}});ConvertTo-Json -Depth 6 -Compress -InputObject $result